Templates.EmbeddedTmpl:
node {
  ip        = "{{ env "attr.unique.network.ip-address" }}"
  port      = {{ env "NOMAD_HOST_PORT_p2p" }}
  bind_port = 14567
  consensus_owner_tracing = false
}
metrics { port = 14568 }
# Explorer stays tunnel-only: the published port lives on tailscale0 and the VM's public
# interface is firewalled, so 0.0.0.0 here never faces the internet.
explorer {
  enabled = true
  ip      = "0.0.0.0"
  port    = 14569
}
# HTTPS, with the node's own self-signed certificate: a browser withholds Web
# Crypto outside a secure context, so over plaintext the client could not hold a
# key at all. Visitors accept the certificate once per node.
client {
  enabled  = true
  ip       = "0.0.0.0"
  port     = 14570
  certfile = ""
  keyfile  = ""
}
# `content` is a LIST — extra ontologies join here too (see the quod-node group's note).
content = [
  {
    namespace = "quod:root"
    data_dir  = "/quod/data/arch206/{{ env "NOMAD_ALLOC_INDEX" }}"
    max_proof_workers = 64
    max_scope_workers = 64
    proof_timeout_ms = 60000
    transaction_ttl_ms = 30000
    batch_window_ms = 25
    scope_timeout_ms = 60000
    scope_step_timeout_ms = 30000
    detailed_consensus_metrics = false
    mode         = join
    genesis_hash = "9F8CD12738E6223B81F68E2DD6D16A278FEA6B583756777D26A06A3FA6135DD4"
    seeds        = [
{{- range service "quod" }}
      "{{ .Address }}:{{ .Port }}",
{{- end }}
    ]
  }
]
